use super::*;

/// Fold new behaviour into accumulated behaviour — counts add, which is all a histogram needs.
pub fn accumulate_behaviour(a: &Behaviour, b: &Behaviour) -> Behaviour {
    let mut dists = Vec::with_capacity(a.dists.len());
    for x in &a.dists {
        let mut counts = x.counts.clone();
        let mut n = x.n;
        if let Some(y) = b.get(&x.name) {
            for (k, v) in &y.counts {
                *counts.entry(k.clone()).or_insert(0) += v;
            }
            n += y.n;
        }
        dists.push(Dist { counts, n, ..x.clone() });
    }
    Behaviour { dists, events: a.events + b.events }
}
